        {"kind": "metric", "sql": "SELECT 'abn' p, metric, attr_k8s_pod_name pod, count(*) n, avg(CAST(value AS DOUBLE)) v, max(CAST(value AS DOUBLE)) mx FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'profile%' AND metric IN ('container.memory.usage','container.cpu.usage') GROUP BY 1,2,3 UNION ALL SELECT 'norm', metric, attr_k8s_pod_name, count(*), avg(CAST(value AS DOUBLE)), max(CAST(value AS DOUBLE)) FROM normal_metrics WHERE attr_k8s_pod_name LIKE 'profile%' AND metric IN ('container.memory.usage','container.cpu.usage') GROUP BY 1,2,3", "claim": "profile pod memory and CPU fall in the abnormal window rather than saturating, so the failure is not resource exhaustion"},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE span_name LIKE 'profile.Profile/%' GROUP BY 1,2,3", "claim": "No profile server spans appear in the abnormal period; every frontend GetProfiles client call errors"},
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.5)/1e6,3) p50_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend' AND span_name='profile.Profile/GetProfiles' GROUP BY 1,2", "claim": "All 1017 frontend calls to profile fail in about 0.02 ms, consistent with no reachable backend"}
      ]
    }
  ],
