      {"kind": "trace", "sql": "SELECT span_name, service_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE span_name IN ('HTTP /hotels','HTTP /recommendations') AND service_name='frontend' GROUP BY 1,2,3,4,5", "claim": "frontend HTTP /hotels and /recommendations server spans all return 500 in the abnormal window, matching the failed profile calls"},
      {"kind": "log", "sql": "SELECT service_name, level, message, count(*) c FROM abnormal_logs WHERE level='ERROR' GROUP BY 1,2,3", "claim": "frontend logs 'Get profiles failed' errors, about 1140 in the abnormal window versus none in normal"}
